import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/products")
class ProductController {

    private final ProductRepository repository;

    ProductController(ProductRepository repository) {
        this.repository = repository;
    }

    // {id:[\d]+} rang buoc bien path chi khop gia tri so.
    @GetMapping("/{id:[\\d]+}")
    ResponseEntity<Product> findById(@PathVariable long id) {
        return repository.findById(id)
                .map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @GetMapping(produces = "application/json")
    ResponseEntity<java.util.List<Product>> search(
            @RequestParam(required = false) String category) {
        var results = category == null
                ? repository.findAll()
                : repository.findByCategory(category);
        return ResponseEntity.ok(results);
    }

    @PostMapping(consumes = "application/json")
    ResponseEntity<Product> create(@RequestBody Product product) {
        Product saved = repository.save(product);
        return ResponseEntity.status(201).body(saved);
    }
}

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.net.URI;
import java.util.List;

record ProductRequest(String name, double price) {}
record ProductResponse(Long id, String name, double price) {}

@RestController
@RequestMapping("/api/products")          // mapping dung chung o cap class
class ProductController {

    // dinh danh tai nguyen -> @PathVariable
    @GetMapping("/{id}")
    ResponseEntity<ProductResponse> getOne(@PathVariable Long id) {
        return ResponseEntity.ok(new ProductResponse(id, "demo", 10.0));
    }

    // tham so phu tro -> @RequestParam co defaultValue
    @GetMapping
    List<ProductResponse> search(@RequestParam(required = false) String keyword,
                                 @RequestParam(defaultValue = "0") int page,
                                 @RequestParam(defaultValue = "20") int size) {
        return List.of();                 // khong tim thay -> 200 + danh sach rong
    }

    // tao moi -> 201 + header Location
    @PostMapping
    ResponseEntity<ProductResponse> create(@RequestBody ProductRequest request) {
        ProductResponse created = new ProductResponse(1L, request.name(), request.price());
        return ResponseEntity.created(URI.create("/api/products/" + created.id())).body(created);
    }

    @DeleteMapping("/{id}")
    ResponseEntity<Void> delete(@PathVariable Long id) {
        return ResponseEntity.noContent().build();   // 204
    }
}

